#C0       ;DEC H       ;LD (HL),B        EX DE,HL        ADD HL,BC        EX DE,HL        INC L        JR NZ,MKTBROW0        ;LD L,0        LD DE,MASKDO        LD C,MASKWIDMKTBMSK LD H,TMASKLN/256        LD (HL),E        INC H        LD (HL),D        LD A,L ;l=y не в маске, а в карте, причём для головы, а не для ног!       add a,8 ;координата для ног       cp SKYHGT       jr nc,MKTBMSKnoblank       ; CP -8       ; JR NC,$+6       ;BIT 5,D       ;JR NZ,$+7         LD (HL),BLANK/256         DEC H         LD (HL),BLANK&0xffMKTBMSKnoblank        RRA         JR NC,$+5         EX DE,HL         ADD HL,BC ;двигаемся каждый второй раз (1 строка маски = 2 строки карты)         EX DE,HL        INC L        JR NZ,MKTBMSK        CALL INIMOUS ;портит ba00                LD HL,TLAND        jr newmapgonowhere ;return here if "nowhere to worm"        LD HL,MESWHE ;"nowhere to worm"newmapgo       ld sp,STACK        CALL MTITLE        call cls        ld hl,panel        call DrawPanel                LD HL,(curdrawingtitle)        CALL DrawTitle ;печать игрового сообщения        CALL MKMAP                ld hl,Tshift        ld de,0x0705        call fixshift        ld h,Tshift/256+2        ld de,0x1f03        call fixshift;TODO сделать нормальный синус;он тут кладётся, т.к. TABSIN затёрта во время генерации карты        ;LD HL,TABSIN        ;XOR A        ;LD B,22        ;LD (HL),A        ;INC HL        ;ADD A,B        ;DJNZ $-3        LD HL,MESHOM        CALL MTITLE        CALL DrawAttrField        CALL ResetTime        CALL DrawEnergyPanel ;печать панельки для энергии и ветра        LD HL,TABROLL        LD C,1MKTRL   LD A,L        AND 31        JR NZ,$+4        RRC C        LD (HL),C        INC L        JR NZ,MKTRL          CALL MAKINTgamemove       call DrawWormsDataInMap       ld a,STATE_MOVE       ld (gamestate),agenwind0        call RND        and 127        cp 46+1+46        jr nc,genwind0        sub 46        ld (wind),a               if 1 ;TODO removegenpowr0        call RND        and 127        cp 119        jr nc,genwind0        ld (powr),a       endif       CALL DrawEnergy ;печать полосок энергии и ветраgameloop       ;EI       ;HALT      ;call MOUSE ;FIXME - для отладки кода с DI        LD HL,(MOUSEx)        LD (MOUSEX),HL        LD A,(MOUSEy)        LD (MOUSEY),A      ;DI    ;CALL MAPPER ;печать верха карты при one frame выводилке        LD A,PGMAP;16        CALL OUTME    call DrawWormsInMap ;TODO рисовать только сместившихся ;даже если напечатали ниже 0xc000, то всё равно сотрём сразу после отрисовки     CALL DrawMap ;TODO не перерисовывать, если не сменился XY и не сместились объекты (прорисовать только строки под стрелкой для air strike)     CALL DrawTime        LD A,PGMAP;16        CALL OUTME    call UnDrawWormsInMap ;TODO стирать только сместившихся    call AnimMines       ;LD A,-64       ;LD HY,'TY4TOP       ;CALL WORMS       ;CALL CURSORoldtitletimer=$+1	ld e,0        ld a,(timer)	ld (oldtitletimer),a	sub e        ld e,aSTCNTa=$+1        LD A,1        sub e;DEC A        JR nc,STNOTIT        xor acurdrawingtitle=$+1        LD HL,TITBUF        CP (HL)        CALL NZ,DrawTitle ;печать игрового сообщения        JR $+5STNOTIT LD (STCNTa),A;DOPR    CALL 0 ;печать низа карты при one frame выводилке;DOPRA   LD HL,0;       LD (HL),#FD;       INC HL;       INC HL;       LD (HL),#E1;       CALL DrawWater;      LD BC,999;      LD D,B;NOLDIR LDIR ;wait for turbo mode (недостаточно при 14 МГц)       ;XOR A       ;LD HY,'TY4LOW       ;CALL CURSOR ;TODO для AIRSTRIKE (надо печатать на карте с запоминанием - прямо перед выводом карты, а потом восстанавливать);logic:;delta timingoldtimer=$+1	ld e,0waithalt        ld a,(timer)	ld (oldtimer),a	sub e         cp 1;2	jp c,timeraction0q;waithaltlogicframesremained=$+1       add a,0 ;0..LOGICSPEED-1timeraction0        ld (logicframesremained),a        sub 1;2        jr c,timeraction0q        push af       CALL WRMOVE       call ControlCurWorm       call WormsVsMines       call StayingWormsVsMovingWorms ;столкновение летящего со стоящим               pop af        jr timeraction0timeraction0q              ld a,(gamestate)       cp STATE_FLY       jr nz,flyingok ;не режим взрыва       call CheckFlyingWorms       jr nz,flyingok ;есть летящие;летящих червей больше нет, печатаем названия всех живых червей и переходим в режим самоубийств (а из него потом или в режим взрыва, или в режим перехода хода)       ld a,STATE_DIE       ld (gamestate),a;TODO...;TODO асинхронно от цикла графики          jp gamemoveflyingok;             ;CALL CLRTOP       ;CALL UPPRU       ;CALL 8020       ;RET NC       LD A,-3       IN A,(-2)       BIT 1,A       CALL Z,unsetwms;SETWMS ;"S" - заново расставить червей       LD A,#FB       IN A,(-2)       BIT 3,A       JP Z,NACHALO ;"R" - заново сгенерировать карту        JP gamelooptimer        db 0 ;for logicwind        db 0 ;-46..46powr        db 0 ;0..118gamestate        db 0 ;STATE_MOVE=управление червём (в т.ч. ИИ), STATE_SHOT=анимация выстрела, STATE_BULLET=полёт снаряда, STATE_FLY=взрыв, STATE_DIE=самоубийства, STATE_NEXTMOVE=переход ходаSTATE_MOVE=0STATE_SHOT=1STATE_BULLET=2STATE_FLY=3STATE_DIE=4STATE_NEXTMOVE=5fixshiftfixshift0        ld b,e        ld a,l        RRCA         DJNZ $-1        ld (hl),a        and d        inc h        ld (hl),a        dec h        xor (hl)        ld (hl),a        inc l        jr nz,fixshift0        retMAKINT        LD A,IMTAB/256        LD I,A        IM 2        EI         RET PRGA    LD A,0OUTME        LD (PRGA+1),AOUTNO        PUSH BC        LD BC,FD        OUT (C),A        POP BC        RET RND        PUSH de        PUSH HL;Patrik Rakrndseed1=$+1        ld  hl,0xA280   ; xz -> ywrndseed2=$+1        ld  de,0xC0DE   ; yw -> zt        ld